<script setup lang="ts">
/**
 * An application's command menus in one row (`design/components/menubar.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/menubar.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import {
  computed,
  onBeforeUnmount,
  onMounted,
  provide,
  ref,
  useId,
  useTemplateRef,
  watch,
} from 'vue'

import * as zag from '@zag-js/menu'
import { normalizeProps, useMachine } from '@zag-js/vue'

import {
  Icon,
  afterRender,
  agentMember,
  chooseMenubarEntry,
  followHighlight,
  menubarChoices,
  menubarEdge,
  menubarEntries,
  menubarNeighbour,
  menubarStop,
  roveMenubar,
  useDirection,
  useMediaQuery,
} from '@polymorph/vue'
import { usePresence } from '@polymorph/vue/motion'
import styles from '@polymorph/recipes/overlays/menubar.module.css'
import Button from '../controls/Button.vue'
import Kbd from '../structure/Kbd.vue'
import Menu, { type MenuEntry } from './Menu.vue'
import MenubarSubmenu from './MenubarSubmenu.vue'

export interface MenubarMenu {
  label: string
  entries: MenuEntry[]
  disabled?: boolean
}

export interface MenubarProps {
  /**
   * The title whose menu is open on mount, for galleries and tests; screens let the user open
   * it.
   */
  defaultOpen?: string
  /**
   * Names the bar, and the one Button the bar becomes at a phone's width.
   */
  label: string
  menus: MenubarMenu[]
}

defineOptions({ name: 'Menubar', inheritAttrs: false })

const props = defineProps<MenubarProps>()
const uid = useId()
const last = ref((props.defaultOpen ?? null) as string | null)
const bar = useTemplateRef<HTMLElement>('bar')
const panel = useTemplateRef<HTMLElement>('panel')
const phone = useMediaQuery('phone')
const stop = computed(() => menubarStop(props.menus, last.value))
const collapsed = computed(() => menubarEntries(props.menus))
const documentDirection = useDirection()
const service = useMachine(
  zag.machine,
  computed(() => ({
    id: uid,
    dir: documentDirection.value,
    defaultOpen: props.defaultOpen !== undefined,
    defaultTriggerValue: props.defaultOpen,
    positioning: { placement: 'bottom-start', gutter: 2 },
    onSelect: (details) => {
      entries.value.forEach(
        (entry) => 'onSelect' in entry && entry.label === details.value && entry.onSelect(),
      )
    },
  })),
)
const api = computed(() => zag.connect(service, normalizeProps))
const entries = computed(
  () => props.menus.find((menu) => menu.label === api.value.triggerValue)?.entries ?? [],
)
const handOff = computed(
  () =>
    (event: KeyboardEvent, child?: { setOpen(open: boolean): void }): void => {
      const to = menubarNeighbour(event, bar.value, panel.value)
      const next = to === undefined ? undefined : props.menus[to]
      if (next === undefined) return
      event.preventDefault()
      event.stopPropagation()
      child?.setOpen(false)
      api.value.setTriggerValue(next.label)
      afterRender(() => {
        const first = menubarEdge(panel.value, 'first')?.getAttribute('data-value')
        if (first) api.value.setHighlightedValue(first)
      })
    },
)
const hover = computed(() => (event: Event, menu: MenubarMenu): void => {
  if (!(event instanceof PointerEvent) || event.pointerType !== 'mouse') return
  if (menu.disabled === true) return
  if (!api.value.open || api.value.triggerValue === menu.label) return
  api.value.setTriggerValue(menu.label)
  // The machine reads an empty value as no row, so the last menu's row is not carried over.
  api.value.setHighlightedValue('')
})
const present = usePresence(() => api.value.open && !phone.value, panel)
provide('polymorph:Menubar', {
  get api() {
    return api.value
  },
  get service() {
    return service
  },
  get handOff() {
    return handOff.value
  },
})
const effect1 = () => {
  followHighlight(panel.value, api.value.highlightedValue)
}
onMounted(effect1)
watch(() => api.value.highlightedValue, effect1, { flush: 'post' })
const effect2 = () => {
  api.value.triggerValue && (last.value = api.value.triggerValue)
}
watch(() => api.value.triggerValue, effect2, { flush: 'post' })
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran = agentMember({
    member: 'Menubar',
    element: () => bar.value,
    state: () => ({ open: api.value.open, entries: menubarChoices(props.menus) }),
    actions: {
      choose: {
        argument: 'id',
        run: (value) =>
          chooseMenubarEntry(props.menus, value) && api.value.open && api.value.setOpen(false),
      },
      close: () => api.value.open && api.value.setOpen(false),
    },
  })
  release3 = () => {
    ran()
  }
}
onMounted(effect3)
onBeforeUnmount(() => release3?.())
</script>

<template>
  <div v-if="phone" :class="styles.collapsed" data-member="menubar">
    <Menu :items="collapsed">
      <template #trigger>
        <Button variant="ghost" tone="neutral" :iconOnly="true" icon="overflow" :label="label" />
      </template>
    </Menu>
  </div>
  <template v-else>
    <!-- bar -->
    <div ref="bar" :class="styles.bar" role="menubar" :aria-label="label" data-member="menubar">
      <template v-for="menu in menus" :key="menu.label">
        <!-- title -->
        <button
          v-bind="api.getTriggerProps({ value: menu.label })"
          :class="styles.title"
          role="menuitem"
          data-menubar-part="title"
          :data-state="api.open && api.triggerValue === menu.label ? 'open' : 'closed'"
          :aria-expanded="api.open && api.triggerValue === menu.label"
          :aria-controls="
            api.open && api.triggerValue === menu.label ? api.getContentProps().id : undefined
          "
          :disabled="menu.disabled === true"
          :data-disabled="menu.disabled === true ? '' : undefined"
          :tabindex="menu.label === stop ? 0 : -1"
          @keydown="roveMenubar($event)"
          @pointerenter="hover($event, menu)"
          @focus="last = menu.label"
        >
          {{ menu.label }}
        </button>
      </template>
    </div>
    <Teleport to="body">
      <div v-if="present" v-bind="api.getPositionerProps()">
        <!-- panel -->
        <div
          ref="panel"
          v-bind="api.getContentProps()"
          :class="styles.content"
          :style="{
            '--radix-dropdown-menu-content-available-height': 'var(--available-height)',
            '--radix-dropdown-menu-content-transform-origin': 'var(--transform-origin)',
          }"
          :hidden="undefined"
          data-menubar-part="panel"
          data-member="menubar"
          @focus="followHighlight(panel, api.highlightedValue)"
          @keydown.capture="handOff($event)"
        >
          <template v-for="(entry, index) in entries" :key="index">
            <div
              v-if="entry.kind === 'separator'"
              v-bind="api.getSeparatorProps()"
              :class="styles.separator"
            />
            <div v-else-if="entry.kind === 'label'" :class="styles.groupLabel">
              {{ entry.label }}
            </div>
            <div
              v-else-if="entry.kind === 'checkbox'"
              v-bind="
                api.getOptionItemProps({
                  type: 'checkbox',
                  value: entry.label,
                  checked: entry.checked,
                  disabled: entry.disabled,
                  closeOnSelect: false,
                  onCheckedChange: entry.onCheckedChange,
                })
              "
              :class="[styles.item, styles.checkbox]"
              tabindex="-1"
              @focus="api.setHighlightedValue(entry.label)"
            >
              <span :class="styles.check">
                <Icon v-if="entry.checked" name="confirm" size="sm" />
              </span>
              <span :class="styles.label">
                {{ entry.label }}
              </span>
            </div>
            <MenubarSubmenu v-else-if="entry.kind === 'submenu'" :entry="entry" />
            <div
              v-else
              v-bind="api.getItemProps({ value: entry.label, disabled: entry.disabled })"
              :class="styles.item"
              :data-tone="entry.tone ?? 'neutral'"
              tabindex="-1"
              @focus="api.setHighlightedValue(entry.label)"
            >
              <span v-if="entry.icon !== undefined" :class="styles.glyph">
                <Icon :name="entry.icon" size="sm" />
              </span>
              <span :class="styles.label">
                {{ entry.label }}
              </span>
              <span v-if="entry.kbd !== undefined" :class="styles.hint">
                <Kbd>
                  {{ entry.kbd }}
                </Kbd>
              </span>
            </div>
          </template>
        </div>
      </div>
    </Teleport>
  </template>
</template>
